mapper.update:
UPDATE public_charge_station
SET rating = #{rating}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, name, location_name as locationName, longitude, latitude, current_type as currentType, price, max_charge_voltage as maxChargeVoltage, max_charge_current as maxChargeCurrent, max_charge_power as maxChargePower, max_vehicles as maxVehicles, current_vehicles as currentVehicles, open_status as openStatus, open_time as openTime, close_time as closeTime, provider, image, description, rating, update_time as updateTime FROM public_charge_station WHERE
longitude BETWEEN #{minLng} AND #{maxLng}
AND
latitude BETWEEN #{minLat} AND #{maxLat}
AND open_status = 1
